window.ScripturaLexicons.BDAG_PART_0356 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-01\" data-source=\"BDAG\" data-search=\"τελευτή, ῆς, ἡ substantivo feminino fim; morte BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελευτή, ῆς, ἡ</td><td>substantivo feminino</td><td>fim; morte</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-02\" data-source=\"BDAG\" data-search=\"τελέω verbo completar; cumprir; pagar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελέω</td><td>verbo</td><td>completar; cumprir; pagar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-03\" data-source=\"BDAG\" data-search=\"τέλος, ους, τό substantivo neutro fim; objetivo; resultado; imposto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέλος, ους, τό</td><td>substantivo neutro</td><td>fim; objetivo; resultado; imposto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-04\" data-source=\"BDAG\" data-search=\"τελωνεῖον remissão ver τελώνιον BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελωνεῖον</td><td>remissão</td><td>ver τελώνιον</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-05\" data-source=\"BDAG\" data-search=\"τελώνης, ου, ὁ substantivo masculino cobrador de impostos BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελώνης, ου, ὁ</td><td>substantivo masculino</td><td>cobrador de impostos</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-06\" data-source=\"BDAG\" data-search=\"τελώνιον, ου, τό substantivo neutro repartição fiscal BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τελώνιον, ου, τό</td><td>substantivo neutro</td><td>repartição fiscal</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-07\" data-source=\"BDAG\" data-search=\"τέξομαι remissão ver τίκτω BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέξομαι</td><td>remissão</td><td>ver τίκτω</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-08\" data-source=\"BDAG\" data-search=\"τέρας, ατος, τό substantivo neutro prodígio; portento; maravilha BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέρας, ατος, τό</td><td>substantivo neutro</td><td>prodígio; portento; maravilha</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-09\" data-source=\"BDAG\" data-search=\"τερατεία, ας, ἡ substantivo feminino ilusão; impostura BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τερατεία, ας, ἡ</td><td>substantivo feminino</td><td>ilusão; impostura</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-10\" data-source=\"BDAG\" data-search=\"Τερέντιος, ου nome próprio Terêncio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τερέντιος, ου</td><td>nome próprio</td><td>Terêncio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-11\" data-source=\"BDAG\" data-search=\"τέρμα, ατος, τό substantivo neutro limite; extremidade BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέρμα, ατος, τό</td><td>substantivo neutro</td><td>limite; extremidade</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-12\" data-source=\"BDAG\" data-search=\"τερπνός, ή, όν adjetivo agradável; aprazível BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τερπνός, ή, όν</td><td>adjetivo</td><td>agradável; aprazível</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-13\" data-source=\"BDAG\" data-search=\"τερπνόω/τερπνέω verbo deleitar-se; estar feliz BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τερπνόω/τερπνέω</td><td>verbo</td><td>deleitar-se; estar feliz</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-14\" data-source=\"BDAG\" data-search=\"Τέρτιος, ου, ὁ nome próprio masculino Tércio BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τέρτιος, ου, ὁ</td><td>nome próprio masculino</td><td>Tércio</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-15\" data-source=\"BDAG\" data-search=\"Τέρτουλλος, ου, ὁ nome próprio masculino Tértulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τέρτουλλος, ου, ὁ</td><td>nome próprio masculino</td><td>Tértulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-16\" data-source=\"BDAG\" data-search=\"Τέρτυλλος, ου, ὁ nome próprio masculino Tértulo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Τέρτυλλος, ου, ὁ</td><td>nome próprio masculino</td><td>Tértulo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-17\" data-source=\"BDAG\" data-search=\"τεσσαράκοντα, τεσσαρακονταετής remissão ver τεσσερ- BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεσσαράκοντα, τεσσαρακονταετής</td><td>remissão</td><td>ver τεσσερ-</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-18\" data-source=\"BDAG\" data-search=\"τέσσαρες numeral cardinal quatro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τέσσαρες</td><td>numeral cardinal</td><td>quatro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-19\" data-source=\"BDAG\" data-search=\"τεσσαρεσκαιδέκατος, η, ον numeral ordinal décimo quarto BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεσσαρεσκαιδέκατος, η, ον</td><td>numeral ordinal</td><td>décimo quarto</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0356-20\" data-source=\"BDAG\" data-search=\"τεσσεράκοντα numeral cardinal indeclinável quarenta BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">τεσσεράκοντα</td><td>numeral cardinal indeclinável</td><td>quarenta</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0356-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελευτή, ῆς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελευτή</span>, <span class=\"greek\">ῆς</span>, <span class=\"greek\">ἡ</span> (Hom. et al. em vários sentidos: ‘consumação, resultado, fim’) aquilo que assinala o ponto em que algo deixa de existir, fim, eufemismo para morte (v. artigo precedente; Pind., Thu. 11:7 et al.; pap., LXX; TestAbr B 10 p. 115, 5 [Stone p. 78]; Test12Patr; ApcMos 5; SibOr 3:363; Jos., Ant. 8, 190; Just., D. 47, 3; Tat. 6, 1; Ath., R. p. 61, 19, com <span class=\"greek\">βιότοιο</span> já em Il. 7, 104) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:15</a>.—DELG s.v. <span class=\"greek\">τέλος</span>. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελέω</span> fut. <span class=\"greek\">τελέσω</span>; 1 aor. <span class=\"greek\">ἐτέλεσα</span>; perf. <span class=\"greek\">τετέλεκα</span>. Pass.: 1 fut. <span class=\"greek\">τελεσθήσομαι</span>; 1 aor. <span class=\"greek\">ἐτελέσθην</span>; perf. <span class=\"greek\">τετέλεσμαι</span> (Hom.+).</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> completar uma atividade ou processo, levar a termo, terminar, completar <span class=\"greek\">τὶ</span> algo. <span class=\"greek\">ταῦτα</span> Hs 8, 2, 5. <span class=\"greek\">τὸν</span> <span class=\"greek\">δρόμον</span> (Il. 23, 373; 768; Soph., El. 726) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TI.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Ti 4:7</a>. <span class=\"greek\">τοὺς</span> <span class=\"greek\">λόγους</span> <span class=\"greek\">τούτους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.28\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:28</a>; 19:1; 26:1 (cf. Just., D. 110, 1). <span class=\"greek\">τὰς</span> <span class=\"greek\">παραβολὰς</span> <span class=\"greek\">ταύτας</span> 13:53. <span class=\"greek\">τὴν</span> <span class=\"greek\">μαρτυρίαν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.11.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 11:7</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">εὐχήν</span> GJs 9:1. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐξήγησιν</span> Hv 3, 7, 4. <span class=\"greek\">τὰ</span> <span class=\"greek\">γράμματα</span> 2, 1, 4. <span class=\"greek\">τελέσας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">χαράκωσιν</span> quando terminou o cercamento Hs 5, 2, 3. <span class=\"greek\">τελεῖν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">κατὰ</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:39</a> (<span class=\"greek\">τελ</span>. <span class=\"greek\">πάντα</span> como em Jos., Ant. 16, 318). <span class=\"greek\">τελ</span>. <span class=\"greek\">τὰς</span> <span class=\"greek\">πόλεις</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">Ἰσραήλ</span> terminar (de percorrer) as cidades de Israel <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.23\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:23</a> (sobre esta passagem KWeiss, Exegetisches z. Irrtumslosigkeit u. Eschatologie Jesu Christi 1916, 184–99; JDupont, NovT 2, ’58, 228–44; AFeuillet, CBQ 23, ’61, 182–98; MKünzi, Das Naherwartungslogion Mt 10:23, ’70 [história da interpretação]). Seguido de um part. para designar aquilo que se termina (B-D-F §414, 2; Rob. 1121; cf. Josh 3:17; JosAs 15:12) <span class=\"greek\">ἐτέλεσεν</span> <span class=\"greek\">διατάσσων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.11.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 11:1</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.1\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:1</a> D; Hv 1, 4, 1.—Pass. ser levado a termo, ser terminado, completado, da construção da torre (cf. 2 Esdr 5:16; 16: 15) Hv 3, 4, 1f; 3, 5, 5; 3, 9, 5; Hs 9, 5, 1; 9, 10, 2 (<span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span>). <span class=\"greek\">τελεσθέντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">δείπνου</span> GJs 6:3 (TestAbr A 5 p. 81, 32 [Stone p. 10]; JosAs 21:8). <span class=\"greek\">ὡς</span> … <span class=\"greek\">ἐτελέσθη</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">πλοῦς</span> AcPl Ha 7, 35. Do tempo, chegar ao fim, acabar (Hom. et al.; Aristot., HA 7, 1, 580a, 14 <span class=\"greek\">ἐν</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἔτεσι</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">δὶς</span> <span class=\"greek\">ἑπτὰ</span> <span class=\"greek\">τετελεσμένοις</span>; Lucian, Alex. 38) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.6\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:6</a> D; analogamente <span class=\"greek\">τοῦ</span> <span class=\"greek\">ἐξεῖναι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">Παῦλον</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">Ῥώμην</span> AcPl Ha 6, 15; <span class=\"greek\">τὰ</span> <span class=\"greek\">χίλια</span> <span class=\"greek\">ἔτη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.20.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 20:3</a>, 5, 7. <span class=\"greek\">πάντα</span> <span class=\"greek\">τετέλεσται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.19.28\" target=\"_blank\" rel=\"noopener noreferrer\">J 19:28</a> (GDalman, Jesus-Jeschua 1922, 211–18 [trad. PLevertoff 1929, mesmas páginas].—Diagoras de Melos em Sext. Emp., Adv. Math. 9, 55 <span class=\"greek\">κατὰ</span> <span class=\"greek\">δαίμονα</span> <span class=\"greek\">κ</span>. <span class=\"greek\">τύχην</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τελεῖται</span>=‘tudo se realiza segundo a vontade divina e a fortuna’; um autor anônimo de mimos [II d.C.] em OCrusius, Herondas5 [p. 110–16] linha 175 <span class=\"greek\">τοῦτο</span> <span class=\"greek\">τετέλεσται</span>); cf. <span class=\"greek\">τετέλεσται</span> empregado absolutamente no v. 30 (se estes dois versículos devem ser entendidos como referentes ao cumprimento [v. 2 abaixo] de determinações divinas contidas nas Escrituras, cf. Diod S 20, 26, 2 <span class=\"greek\">τετελέσθαι</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">χρησμόν</span>=o oráculo havia sido cumprido; Ael. Aristid. 48, 7 K.=24 p. 467 D.: <span class=\"greek\">μέγας</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">Ἀσκληπιός</span>· <span class=\"greek\">τετέλεσται</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσταγμα</span>. Cf. Willibald Schmidt, De Ultimis Morientium Verbis, diss. Marburg 1914. OCullmann, TZ 4, ’48, 370 interpreta os dois versículos tanto em sentido cronológico quanto teol. Diod S 15, 87, 6 relata as quatro últimas palavras de Epaminondas, duas em discurso indireto e as outras duas em discurso direto. V. também as últimas palavras de Filipe s.v. <span class=\"greek\">πληρόω</span> 5).—<span class=\"greek\">ἡ</span> <span class=\"greek\">δύναμις</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">ἀσθενείᾳ</span> <span class=\"greek\">τελεῖται</span> o poder encontra sua consumação ou alcança a perfeição na (presença da) fraqueza <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.12.9\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 12:9</a>. Os passivos em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.10.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 10:7</a> (o aor. sugere o ‘esclarecimento definitivo de todos os enigmas e problemas insolúveis da vida humana’: EBlakeney, The Epistle to Diognetus ’43, ’67); 15:1, 8; 17:17 pertencem tanto a 2 quanto a esta acepção.</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> cumprir uma obrigação ou exigência, executar, realizar, desempenhar, cumprir, observar <span class=\"greek\">τὶ</span> algo. (Hom.+. De ritos, jogos, procissões etc., dedicados a uma divindade ou por ela determinados: Eur., Bacch. 474 <span class=\"greek\">τὰ</span> <span class=\"greek\">ἱερά</span>; Pla., Laws 775a; X., Resp. Lac. 13, 5; Plut., Mor. 671 al.; Just., A II, 12, 5 <span class=\"greek\">μυστήρια</span>; Mel., P. 16, 102 <span class=\"greek\">μυστήριον</span> al.; nas inscr. frequentemente de serviço público, p. ex. IPriene 111, 22 uma embaixada) <span class=\"greek\">τὸν</span> <span class=\"greek\">νόμον</span> cumprir as exigências da lei, observar a lei <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.2.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 2:27</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.2.8\" target=\"_blank\" rel=\"noopener noreferrer\">Js 2:8</a>. <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐντολήν</span> Hs 5, 2, 4 (Jos., Bell. 2, 495 <span class=\"greek\">τὰς</span> <span class=\"greek\">ἐντολάς</span>). <span class=\"greek\">τὸ</span> <span class=\"greek\">ἔργον</span> (Theogn. 914; Apollon. Rhod. 4, 742; Sir 7:25) 2:7a; 5, 2, 7. <span class=\"greek\">τὴν</span> <span class=\"greek\">διακονίαν</span> m 2:6ab; 12, 3, 3; Hs 2:7b; pass. m 2:6c. <span class=\"greek\">τὰς</span> <span class=\"greek\">διακονίας</span> Hs 1:9. <span class=\"greek\">τὴν</span> <span class=\"greek\">νηστείαν</span> 5, 1, 5; 5, 3, 8. <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">σαρκὸς</span> <span class=\"greek\">τελεῖν</span> realizar o que a carne deseja, satisfazer os próprios desejos físicos (Artem. 3, 22; Achilles Tat. 2, 13, 3 <span class=\"greek\">αὑτῷ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιθυμίαν</span> <span class=\"greek\">τελέσαι</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.5.16\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 5:16</a>. <span class=\"greek\">ὡς</span> <span class=\"greek\">ἐτέλεσαν</span> <span class=\"greek\">πάντα</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">γεγραμμένα</span> quando haviam cumprido tudo o que estava escrito (nas Escrituras) a seu respeito <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.13.29\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 13:29</a> (Appian, Bell. Civ. 3, 59 §243 <span class=\"greek\">τὸ</span> <span class=\"greek\">κεκριμένον</span> <span class=\"greek\">τ</span>.=executar o que fora decidido). Pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.31\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:31</a>; 22:37 (cf. pass. citado em 1, final). <span class=\"greek\">ἕως</span> <span class=\"greek\">ὅτου</span> <span class=\"greek\">τελεσθῇ</span> até que se cumpra (o batismo) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.50\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:50</a>. <span class=\"greek\">ἵνα</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τύπος</span> <span class=\"greek\">τελεσθῇ</span> a fim de que o tipo se cumprisse B 7:3.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> pagar o que é devido, pagar (Hom., Pla., et al.; pap.; Jos., Ant. 2, 192 al.) <span class=\"greek\">φόρους</span> (Ps.-Pla., Alc. 1, 123a <span class=\"greek\">τὸν</span> <span class=\"greek\">φόρον</span>; Appian, Syr. 44 §231; PFay 36, 14 [111/12 d.C.]; Philo, Agr. 58; Jos., Ant. 15, 106; Just., A I, 17, 2 <span class=\"greek\">φόρους</span> <span class=\"greek\">τελεῖν</span> [Luke 20:22]; Tat. 4:1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.6\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:6</a>. <span class=\"greek\">τὰ</span> <span class=\"greek\">δίδραχμα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.24\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:24</a>. V.l. de <span class=\"greek\">τελευτάω</span> Papias (4).—B. 797. DELG s.v. <span class=\"greek\">τέλος</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέλος, ους, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέλος</span>, <span class=\"greek\">ους</span>, <span class=\"greek\">τό</span> (Hom.+)</p><p class=\"entry-text\"><span class=\"sense-number\">①</span> ponto no tempo que assinala o fim de uma duração, fim, término, cessação (Nicol. Dam.: 90 Fgm. 130 §139 Jac. <span class=\"greek\">τέλος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Βίου</span> <span class=\"greek\">Καίσαρος</span>; TestAbr A 1 p. 78, 5 [Stone p. 4] <span class=\"greek\">τῆς</span> <span class=\"greek\">ζωῆς</span>; Maximus Tyr. 13, 9d <span class=\"greek\">ἀπιστίας</span>) <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔσται</span> <span class=\"greek\">τέλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.1.33\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 1:33</a>. <span class=\"greek\">μήτε</span> <span class=\"greek\">ἀρχὴν</span> <span class=\"greek\">ἡμερῶν</span> <span class=\"greek\">μήτε</span> <span class=\"greek\">ζωῆς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.7.3\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 7:3</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">καταργουμένου</span> o fim do (esplendor) que se desvanece <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 3:13</a>. <span class=\"greek\">τέλος</span> <span class=\"greek\">νόμου</span> <span class=\"greek\">Χριστός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:4</a> (talvez 3 abaixo). <span class=\"greek\">πάντων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἤγγικεν</span> o fim de todas as coisas está próximo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:7</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Ἰερουσαλήμ</span> GPt 7:25. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">κυρίου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:11</a> é frequentemente (desde Agostinho até ABischoff, ZNW 7, 1906, 274–79) entendido incorretamente como o fim=a morte (é isto que <span class=\"greek\">τέλος</span> significa, p. ex., TestAbr A 4, p. 81, 14 [Stone p. 10]; Appian, Syr. 64 §342, Bell. Civ. 1, 107 §501; 3, 98 §408; Arrian, Anab. 3, 22, 2; 7, 24, 1) do Senhor Jesus (v. 3 abaixo). <span class=\"greek\">τ̣ὸ̣</span> [<span class=\"greek\">τέλο</span>]<span class=\"greek\">ς</span> (ou <span class=\"greek\">τ̣ε̣</span>[<span class=\"greek\">λο</span>]<span class=\"greek\">ς</span>) <span class=\"greek\">τῶν</span> <span class=\"greek\">φαινο</span>[<span class=\"greek\">με</span>]<span class=\"greek\">νων</span> (leitura de Till de Ox 1081, 29f segundo o copta SJCh 90, 6, em lugar de <span class=\"greek\">τ̣ὸ̣</span> [<span class=\"greek\">φῶ</span>]<span class=\"greek\">ς</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">φαινο</span>[<span class=\"greek\">μέ</span>]<span class=\"greek\">νων</span>) o fim das coisas que são aparentes. <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχειν</span> ter fim, estar no fim (X., An. 6, 5, 2; Pla., Phdr. 241d, Rep. 3, 392c; Diod S 14, 18, 8; 16, 91, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.3.26\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 3:26</a> (oposto a <span class=\"greek\">στῆναι</span>). A possibilidade de arrepender-se <span class=\"greek\">ἔχει</span> <span class=\"greek\">τέλος</span> chegou ao fim Hv 2, 2, 5. Da consumação que sobrevém às profecias quando se cumprem (Xenophon Eph. 5, 1, 13; Jos., Ant. 2, 73; 4, 125; 10, 35; SibOr 3, 211): revelações Hv 3, 3, 2. Assim talvez <span class=\"greek\">τὸ</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχει</span> as referências (nas Escrituras) a mim estão se cumprindo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:37</a>; também provável é a obra de minha vida chegou ao fim (cf. Diod S 20, 95, 1 <span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχειν</span> de máquinas de cerco, cuja construção acarretou muito trabalho árduo: estar concluído; Plut., Mor. 615e; Jos., Vi. 154).</p><p class=\"entry-text\"><span class=\"sense-number\">②</span> a última parte de um processo, encerramento, conclusão, esp. das últimas coisas, o ato final do drama cósmico (Sb 8422, 10 [7 a.C.] <span class=\"greek\">τοῦτο</span> <span class=\"greek\">γάρ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">τέλος</span>; TestAbr A 13 p. 92, 19 [Stone p. 32] <span class=\"greek\">τῆς</span> <span class=\"greek\">κρίσεως</span> <span class=\"greek\">ἐκείνης</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span>; ApcEsdr 3:13 <span class=\"greek\">ἐγγύς</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span>; Iren., 1, 10, 3 [Harv. I 96, 8] <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">καὶ</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">μέλλόντων</span>)</p><p class=\"entry-text\"><span class=\"sense-number\">ⓐ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.6\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:6</a>, 14; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:7</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.21.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 21:9</a>; PtK 2 p. 13, 22. Talvez <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a>, se <span class=\"greek\">ἔσται</span> deve ser suprido com <span class=\"greek\">εἶτα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> então virá o fim (assim JHéring, RHPR 12, ’33, 300–320; v. abaixo, b<span class=\"greek\">α</span> e 4). <span class=\"greek\">ἔχει</span> <span class=\"greek\">τέλος</span> o fim chegou Hv 3, 8, 9. Sobre <span class=\"greek\">τὰ</span> <span class=\"greek\">τέλη</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">αἰώνων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:11</a> v. <span class=\"greek\">αἰών</span> 2b e 5 abaixo; também MBogle, ET 67, ’56, 246f: <span class=\"greek\">τ</span>.=‘mistério’.—PVolz, D. Eschatologie d. jüd. Gemeinde im ntl. Zeitalter ’34; Bousset, Rel.3 202–301; EHaupt, Die eschatol. Aussagen Jesu in den synopt. Evangelien 1895; HSharman, The Teaching of Jesus about the Future acc. to the Synopt. Gospels 1909; FSpitta, Die grosse eschatol. Rede Jesu: StKr 82, 1909, 348–401; EvDobschütz, The Eschatology of the Gospels 1910, Zur Eschatol. der Ev.: StKr 84, 1911, 1–20; PCorssen, Das apokalypt. Flugblatt in der synopt. überl.: Wochenschr. für klass. Philol. 32, 1915, n.os 30f; 33f; DVölter, Die eschat. Rede Jesu: SchTZ 32, 1915, 180–202; KWeiss (v. <span class=\"greek\">τελέω</span> 1); JWeiss, Das Urchristent. 1917, 60–98; JJeremias, Jesus als Weltvollender 1930; WKümmel, Die Eschatologie der Ev.: ThBl 15, ’36, 225–41, Verheissg. u. Erfüllg. ’45; CCadoux, The Historic Mission of Jesus ’41 (escat. dos sinóticos); HPreisker, Das Ethos des Urchristentums ’49; AStrobel, Untersuchungen zum eschat. Verzögerungsproblem, ’61. Billerb. IV 799–976. V. também <span class=\"greek\">ἀνάστασις</span> 2b, final.—Em contraste com <span class=\"greek\">ἀρχή</span>: B 1:6ab; IEph 14:1ab; IMg 13:1. De Deus <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:8</a> v.l.; 21:6; 22:13 (Ar. 4, 2; Just., D. 7, 2; Mel., P. 105, 113f; v. também <span class=\"greek\">ἀρχή</span> 2).</p><p class=\"entry-text\"><span class=\"sense-number\">ⓑ</span> expressões adverbiais</p><p class=\"entry-text\"><span class=\"greek\">α</span>. acus. adv. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> finalmente (Pla. et al.; BGU 1024 VII, 23; B-D-F §160; v. Rob. 486–88; Theoph. Ant. 1, 14 [p. 92, 8].—O uso habitual neste caso é <span class=\"greek\">τέλος</span> sem o art.: ViAm 1 [p. 81, 11 Sch.]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.3.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 3:8</a>. <span class=\"greek\">εἶτα</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a> é classificado aqui por Hofmann2; FBurkitt, JTS 17, 1916, 384f; KBarth, Die Auferstehung der Toten2 1926, 96 (v. 2a acima e 4 abaixo).</p><p class=\"entry-text\"><span class=\"greek\">β</span>. até o fim, até o último momento: <span class=\"greek\">ἄχρι</span> <span class=\"greek\">τέλους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.11\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.2.26\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 2:26</a>; <span class=\"greek\">ἕως</span> <span class=\"greek\">τέλους</span> (Da 6:27 Theod.; JosAs 12:3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 1:8</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 1:13</a> (aqui também significa até o fim=até a parusia [Windisch, Sickenberger, NRSV], e não ‘plenamente’ [Ltzm., Hdb.; RSV ’46]); Hs 9, 27, 3; <span class=\"greek\">μέχρι</span> <span class=\"greek\">τέλους</span> (Phocylides [VI a.C.] 17 Diehl3 <span class=\"greek\">ἐξ</span> <span class=\"greek\">ἀρχῆς</span> <span class=\"greek\">μέχρι</span> <span class=\"greek\">τέλους</span>; Chariton 4, 7, 8; Appian, Mithrid. 112 §550; Polyaenus 4, 6, 11; POxy 416, 3; PTebt 420, 18; Wsd 16:5; 19:1; Jos., Vi. 406) Hb 3:6 v.l., 14; Dg 10:7. V. também <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> (<span class=\"greek\">γ</span> abaixo).</p><p class=\"entry-text\"><span class=\"greek\">γ</span>. <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> no fim, finalmente (Hdt. 3, 40 et al.; PTebt 38, 11 [113 a.C.]; 49, 12; Gen 46:4; GrBar 13:2; Ps.-Clem., Hom. 18, 2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.5\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:5</a>. <span class=\"greek\">σωθῆναι</span> 2 Cl 19:3.—Até o fim, até o término (Epict. 1, 7, 17; Jos., Ant. 19, 96; JosAs 23:5) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:22</a>; 24:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.13.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 13:13</a>; IEph 14:2; IRo 10:3.—Para sempre, por toda a eternidade (Dionys. Hal. 13, 88, 3; Ps 9:19; 76:9; 1 Ch 28:9; Da 3:34) <span class=\"greek\">ἔφθασεν</span> <span class=\"greek\">ἐπ</span>’ <span class=\"greek\">αὐτοὺς</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">ὀργὴ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TH.2.16\" target=\"_blank\" rel=\"noopener noreferrer\">1 Th 2:16</a> (v. também abaixo e cf. TestLevi 6:11, a respeito do qual há diversidade de opiniões). <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἀπολέσαι</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ζωήν</span> perder a vida para sempre Hs 8, 8, 5b.—Decisivamente, extremamente, plenamente, inteiramente (Polyb. 1, 20, 7; 10; 12, 27, 3 e frequentemente; Diod S 18, 57, 1 <span class=\"greek\">ταπεινωθέντες</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>.=completamente arruinados; Lucian, Philop. 14; Appian, Bell. Mithr. 44 §174; OGI 90, 12 [II a.C.]; PTebt 38, 11 [II a.C.]; 49, 11; 793 [v. <span class=\"greek\">οὖς</span> 1]; Josh 8:24; 2 Ch 12:12; Ps 73:1; Job 6:9; PsSol 1:1; TestAbr A 13 p. 92, 23 [Stone p. 32]; ApcMos 19; Jos., Vi. 24; Just., A I, 44, 12; Diodorus sobre Ps 51:7: MPG 33, 1589b <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τουτέστι</span> <span class=\"greek\">παντελῶς</span>) 1 Th 2:16 (para sempre também é provável; v. acima); B 4:7; 10:5; 19:11. <span class=\"greek\">ἱλαρὰ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἦν</span> ela estava muito alegre Hv 3, 10, 5. Cf. 3, 7, 2; m 12, 2, 3; Hs 6, 2, 3; 8, 6, 4; 8, 8, 2; 5a; 8, 9, 3; 9, 14, 2.—Para <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἠγάπησεν</span> <span class=\"greek\">αὐτούς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.1\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:1</a> v. <span class=\"greek\">εἰς</span> 3.</p><p class=\"entry-text\"><span class=\"greek\">δ</span>. <span class=\"greek\">ἐν</span> <span class=\"greek\">τέλει</span> no fim (oposto a <span class=\"greek\">πρὸ</span> <span class=\"greek\">αἰώνων</span>) IMg 6:1.</p><p class=\"entry-text\"><span class=\"sense-number\">③</span> o objetivo para o qual um movimento está dirigido, fim, objetivo, resultado (Dio Chrys. 67 [17], 3; Epict. 1, 30, 4; 3, 24, 7; Maximus Tyr. 20, 3b; Jos., Ant. 9, 73; TestAsh 1:3; <span class=\"greek\">ἡ</span> <span class=\"greek\">θεία</span> <span class=\"greek\">παίδευσις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">εἰσαγωγὴν</span> <span class=\"greek\">ἔχει</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">προκοπὴν</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">τ</span>. Did., Gen. 69, 9) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.58\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:58</a>. <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">κυρίου</span> o resultado que o Senhor produziu no caso das provações de Jó <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.11\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:11</a> (Diod S 20, 13, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ὑπερηφάνως</span> <span class=\"greek\">διαλογιζομένοις</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">κατελπισθέντων</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τοὐναντίον</span> <span class=\"greek\">μετατίθησιν</span>=a divindade, no caso dos arrogantes, transforma o resultado do que esperavam em seu contrário.—Sobre Js 5:11 v. 1 acima). <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">παραγγελίας</span> <span class=\"greek\">ἐστὶν</span> <span class=\"greek\">ἀγάπη</span> a instrução tem o amor por objetivo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1TI.1.5\" target=\"_blank\" rel=\"noopener noreferrer\">1 Ti 1:5</a> (<span class=\"greek\">Ἐπίκουρος</span> … <span class=\"greek\">λέγων</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">σοφίας</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">ἡδονήν</span> Hippol., Ref. 1, 22, 4. <span class=\"greek\">τ</span>.=‘objetivo’ ou ‘propósito’: Epict. 1, 20, 15; 4, 8, 12; Diog. L. 2, 87; Just., D. 2, 6). Talvez aqui se enquadre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.10.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 10:4</a>, no sentido de que Cristo é ao mesmo tempo o objetivo e o término da lei, aproximadamente no sentido de <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/GAL.3.24\" target=\"_blank\" rel=\"noopener noreferrer\">Gal 3:24f</a> (escol. sobre Pla., Leg. 625d <span class=\"greek\">τέλος</span> <span class=\"greek\">τῶν</span> <span class=\"greek\">νόμων</span>=objetivo das leis; Plut., Mor. 780e <span class=\"greek\">δίκη</span> … <span class=\"greek\">νόμου</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἐστί</span>; FFlückiger, TZ 11, ’55, 153–57; diferentemente RJewett, Int 39, ’85, 341–56, Cristo como objetivo, mas sem repúdio da lei; cf. SBechtler, CBQ 56, ’94, 288–308); v. 1.—Esp. também do objetivo final para o qual pessoas e coisas tendem, do resultado ou destino que as aguarda de acordo com sua natureza (TestAsh 6:4; Philo, Exs. 162, Virt. 182; Just., A II, 3, 7; Ath., R. 24 p. 77, 19; Aelian, VH 3, 43; Alciphron 4, 7, 8; Procop. Soph., Ep. 154; <span class=\"greek\">τὸ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὁρόμου</span> Orig., C. Cels. 7, 52, 6) <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ἐκείνων</span> <span class=\"greek\">θάνατος</span> … <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">ζωὴν</span> <span class=\"greek\">αἰώνιον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.6.21\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 6:21f</a>. Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.15\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/PHP.3.19\" target=\"_blank\" rel=\"noopener noreferrer\">Phil 3:19</a> (HKoester, NTS 8, ’61/62, 325f): talvez um jogo de palavras com um termo dos mistérios; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.17\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:17</a> (cf. 2 Macc 7:30–38); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.6.8\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 6:8</a>. <span class=\"greek\">κομιζόμενοι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πίστεως</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:9</a>. <span class=\"greek\">τέλος</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πράγματα</span> <span class=\"greek\">ἔχει</span> todas as coisas têm um objetivo ou destino final (isto é, morte ou vida) IMg 5:1 (<span class=\"greek\">τέλος</span> <span class=\"greek\">ἔχειν</span> como em Plut., Mor. 382e; Polyaenus 4, 2, 11 <span class=\"greek\">τέλος</span> <span class=\"greek\">οὐκ</span> <span class=\"greek\">ἔσχεν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">πρᾶξις</span>=não atingiu seu objetivo; Jos., C. Ap. 2, 181, Ant. 17, 185.—Ael. Aristid. 52 p. 597 D.: <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">πάντων</span> <span class=\"greek\">πραγμάτων</span>). <span class=\"greek\">εἰς</span> <span class=\"greek\">τέλος</span> <span class=\"greek\">εἶναι</span> estar no = atingir o objetivo IRo 1:1 (<span class=\"greek\">εἰς</span> em lugar de <span class=\"greek\">ἐν</span>; v. <span class=\"greek\">εἰς</span> 1a<span class=\"greek\">δ</span>).</p><p class=\"entry-text\"><span class=\"sense-number\">④</span> último de uma série, resto, remanescente (Aristot. De Gen. Anim. 1, 18 p. 725b, 8; Is 19:15. De uma formação militar Arrian, Tact. 10, 5; 18, 4), se <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.15.24\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 15:24</a> deve ser entendido, com JWeiss e Ltzm., como um terceiro e último grupo (<span class=\"greek\">τάγμα</span> 1b; v. 2a e 2b<span class=\"greek\">α</span> acima).</p><p class=\"entry-text\"><span class=\"sense-number\">⑤</span> obrigação tributária, imposto (indireto), pedágio, direitos aduaneiros (X., Pla. et al.; inscr., pap.; 1 Macc 10:31; 11:35; Jos., Ant. 12, 141) <span class=\"greek\">ἀποδιδόναι</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">τέλος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.13.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 13:7b</a>; cf. a (com <span class=\"greek\">φόρος</span> como Appian, Sicil. 2, 6, Bell. Civ. 2, 13 §47; Vi. Aesopi W 92; Ps.-Clem., Hom. 10, 22. Pl. com <span class=\"greek\">εἰσφοραί</span> Theoph. Ant. 1, 10 [p. 80, 19]). <span class=\"greek\">λαμβάνειν</span> <span class=\"greek\">τέλη</span> <span class=\"greek\">ἀπό</span> <span class=\"greek\">τινος</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.25\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:25</a> (com <span class=\"greek\">κῆνσος</span>; Just., A I, 27, 2).—<span class=\"greek\">τὰ</span> <span class=\"greek\">τέλη</span> <span class=\"greek\">τ</span>. <span class=\"greek\">αἰώνων</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 10:11</a> é traduzido como as receitas (espirituais) dos séculos por ASouter (Pocket Lex. of the NT 1916, s.v. <span class=\"greek\">τέλος</span>) e PMacpherson, ET 55, ’43/44, 222 (v. 2a acima).—GDelling, TW VIII, 50–88: <span class=\"greek\">τέλος</span> e palavras afins, também ZNW 55, ’64, 26–42=Studien zum NT, ’70, 17–31.—B. 802; 979. Schmidt, Syn. IV 496–523. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελωνεῖον</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελωνεῖον</span> v. <span class=\"greek\">τελώνιον</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελώνης, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελώνης</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">τέλος</span>, <span class=\"greek\">ὠνέομαι</span> ou o substantivo afim <span class=\"greek\">ὠνή</span> ‘compra, aquisição’; Aristoph., Aeschin. et al.; inscr., pap., óstracos) cobrador de impostos, agente fiscal (cf. <span class=\"greek\">τέλος</span> 5; Goodsp., Probs. 28; sobre a extensão semântica de <span class=\"greek\">τελώνη</span> v. New Docs 5, 103; cf. JVergote, Eos 48, ’56, 149–60, v. p. 149). Os <span class=\"greek\">τελ</span>. nos sinóticos (a única parte de nossa lit. em que são mencionados) não são os titulares (lat. publicani) dos próprios contratos de arrendamento da cobrança de impostos, mas subordinados (lat. portitores) por eles contratados; os funcionários superiores eram geralmente estrangeiros, mas seus subordinados, em regra, eram recrutados entre a população nativa. O sistema de arrecadação então vigente proporcionava ao cobrador muitas oportunidades de exercer a cobiça e a injustiça. Por isso os cobradores de impostos eram particularmente odiados e desprezados como classe (v. estes juízos condenatórios sobre os <span class=\"greek\">τελῶναι</span>: Demochares [300 a.C.] 75 Fgm. 4 Jac. <span class=\"greek\">τελ</span>. <span class=\"greek\">βάναυσος</span>; Xeno Com. III 390 Kock <span class=\"greek\">πάντες</span> <span class=\"greek\">τελῶναι</span> <span class=\"greek\">ἅρπαγες</span>; Herodas 6, 64; Diogenes, Ep. 36, 2; Lucian, Necyom. 11; Artem. 1, 23; 4, 42; 57; Heraclid. Crit., Reisebilder 7 p. 76, 6 Pfister; Ps.-Dicaearchus p. 143, 7 Fuhr.; Iambl. Erot. 34; Cicero, De Off. 1, 150; UPZ 113, 9; 16 [156 a.C.]; O. Wilck I 568f; PPrinc II, 20, 1ff [sobre isto OReinmuth, ClPh 31, ’36, 146–62]; Philo, Spec. Leg. 2, 93ff. Material rabínico em Schürer I 374–76; Billerb. I 377f, 498f). Um israelita rigoroso ainda se escandalizava com o fato de que os cobradores de impostos tinham de manter contato contínuo com não israelitas no exercício de seu trabalho; isto tornava um cobrador israelita cerimonialmente impuro. A atitude predominante é expressa nestas combinações: <span class=\"greek\">τελῶναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ἁμαρτωλοί</span> (v. <span class=\"greek\">ἁμαρτωλός</span> b<span class=\"greek\">β</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:10f</a>; 11:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:15</a>, 16ab (RPesch, BRigaux Festschr., ’70, 63–87; cf. Theophr., Characters 6, 47); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.30\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:30</a>; 7:34; 15:1 (JJeremias, ZNW 30, ’31, 293–300). <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐθνικὸς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τελώνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.17\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:17</a>. <span class=\"greek\">οἱ</span> <span class=\"greek\">τελῶναι</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">αἱ</span> <span class=\"greek\">πόρναι</span> 21:31f. Como tipicamente egoístas 5:46.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:12</a> (Sb 8072, 6 [II d.C.] um prefeito repreende <span class=\"greek\">τελ</span>. que exigem <span class=\"greek\">τὰ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">ὀφιλόμενα</span> <span class=\"greek\">αὐτοῖς</span>); 5:29; 7:29. Um fariseu e um cobrador de impostos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.18.10\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 18:10f</a>, 13. <span class=\"greek\">Μαθθαῖος</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τελώνης</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.10.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 10:3</a> (Jos., Bell. 2, 287 <span class=\"greek\">Ἰωάννης</span> <span class=\"greek\">ὁ</span> <span class=\"greek\">τελώνης</span>). <span class=\"greek\">τελ</span>. <span class=\"greek\">ὀνόματι</span> <span class=\"greek\">Λευί</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:27</a> (cf. <span class=\"greek\">Λευί</span> 4).—Schürer I 372–76; JMarquardt, Staatsverw. II2 1884, 261ff; 289ff; AJones, Studies in Rom. Gov’t. and Law, ’60, 101–14; JDonahue, CBQ 33, ’71, 39–61; EBadian, Publicans and Sinners ’72; WWalker, JBL 97, ’78, 221–38; FHerrenbrück, ZNW 72, ’81, 178–94, Jesus und die Zöllner ’90; DBraud, Gabinus, Caesar, and the ‘publicani’ of Judaea: Klio 65, ’83, 241–44; MGoodman, The Ruling Class of Judaea ’87. V. <span class=\"greek\">κῆνσος</span>.—Kl. Pauly V 1551; BHHW III 2245f.—New Docs 5, 103, também 8, 47–56. DELG s.v. <span class=\"greek\">τέλο</span> e <span class=\"greek\">ὀνέομαι</span>. Frisk s.v. <span class=\"greek\">τέλο</span> e <span class=\"greek\">ὦνο</span>. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τελώνιον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τελώνιον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> repartição fiscal/tributária (v. <span class=\"greek\">τελώνης</span>; Posidippus Com. [III a.C.], Fgm. 13; Strabo 16, 1, 27 [provavelmente ‘operação de cobrança de pedágios’]; 17, 1, 16 [‘posto de cobrança de pedágios’], diferentemente L-S-J-M; OGI 496, 9; 525, 10; UPZ 112 VIII, 3 [203/202 a.C.]; Mitt-Wilck. I/2, 223, 3) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.9.9\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 9:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.5.27\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 5:27</a>; GEb 34, 61 (PPetr II, 11 [2], 3 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τελώνιον</span>).—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέξομαι</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέξομαι</span> v. <span class=\"greek\">τίκτω</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέρας, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέρας</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (Hom. et al.) algo que causa assombro por sua associação com o transcendente, prodígio, portento, presságio, maravilha, em nossa lit. somente no pl. e combinado com <span class=\"greek\">σημεῖα</span>; v. <span class=\"greek\">σημεῖον</span> 2a<span class=\"greek\">β</span> e b, onde são dadas todas as passagens que contêm <span class=\"greek\">τέρατα</span> (ViZech 2; Appian, Bell. Civ. 1, 83 §377 <span class=\"greek\">τέρατα</span> <span class=\"greek\">πολλὰ</span> <span class=\"greek\">ἐγίνοντο</span>, isto é, portentos aterradores causados por uma divindade [<span class=\"greek\">τὸ</span> <span class=\"greek\">δαιμόνιον</span>, <span class=\"greek\">ὁ</span> <span class=\"greek\">θεός</span>] que predizem os resultados destrutivos da campanha de Sula na Itália).—PStein, <span class=\"greek\">ΤΕΡΑΣ</span>, diss. Marburg 1909. DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τερατεία, ας, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τερατεία</span>, <span class=\"greek\">ας</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">τέρας</span>; Aristoph., Isocr. et al.; Eus., PE 63; 132) aquilo que se relaciona com coisas maravilhosas, ilusão, prestidigitação, impostura (Aristoph., Isocr. et al.; Polyb. 2, 17, 6; Diod S 4, 51, 3; Heraclit. Sto. 27 p. 42, 10; Jos., Bell. 1, 630) em sátira Dg 8:4 (com <span class=\"greek\">πλάνη</span>).—EPlümacher ZNW 89, ’98, 66–90 (lit.).</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τερέντιος, ου</h1><div class=\"entry-meta\"><span>nome próprio</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τερέντιος</span>, <span class=\"greek\">ου</span> (gentilício lat.) Terêncio <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:22</a> v.l.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέρμα, ατος, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέρμα</span>, <span class=\"greek\">ατος</span>, <span class=\"greek\">τό</span> (cf. <span class=\"greek\">τέρμων</span> ‘limite’; Hom. et al.; GDI 711; PFay 217 <span class=\"greek\">βίου</span> <span class=\"greek\">τέρμα</span>; Sb 5829, 12; 3 Km 7:32; Wsd 12:27; SibOr 3, 756) posição no limite de uma extensão, extremidade, limite, fronteira (Hdt. 7, 54 <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τέρμα</span> <span class=\"greek\">τ</span>. <span class=\"greek\">Εὐρώπης</span> <span class=\"greek\">γίνεσθαι</span>; Philostrat., Vi. Apoll. 5, 4; En 106:8; Philo, Mos. 1, 2 <span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. <span class=\"greek\">γῆς</span> <span class=\"greek\">τέρματα</span>; Jos., Bell. 7, 284; Tat. 20, 2) <span class=\"greek\">τὸ</span> <span class=\"greek\">τέρμα</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">δύσεως</span> os limites mais remotos do ocidente 1 Cl 5:7 (as várias interpretações da expr. são tratadas por Dubowy [s.v. <span class=\"greek\">Σπανία</span>] 17–79). Sobre a questão da viagem de Paulo à Espanha v. lit. s.v. <span class=\"greek\">Σπανία</span>.—DELG s.v. <span class=\"greek\">τέρμα</span> A.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τερπνός, ή, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τερπνός</span>, <span class=\"greek\">ή</span>, <span class=\"greek\">όν</span> (Tyrtaeus [VII a.C.] et al.; LXX; SibOr 4, 191) deleitável, agradável, aprazível 1 Cl 7:3 (cf. Ps 132:1). Subst. (<span class=\"greek\">τὸ</span> <span class=\"greek\">τερπνόν</span> Polyb. 1, 4, 11; EpArist 77; Jos., Ant. 19, 181; <span class=\"greek\">τὰ</span> <span class=\"greek\">τ</span>. Isocr. 1, 21; Philo, Somn. 2, 209) <span class=\"greek\">τὰ</span> <span class=\"greek\">τερπνὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κόσμου</span> os deleites ou prazeres do mundo IRo 6:1 (assim Zahn, com os testemunhos gregos do texto não interpolado, embora Lghtf., Funk, Hilgenfeld, GKrüger e Bihlmeyer, com o grego interpolado e as versões lat. e sir., prefiram <span class=\"greek\">πέρατα</span>, v. Bihlmeyer app. ad loc.).—DELG s.v. <span class=\"greek\">τέρπομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τερπνόω/τερπνέω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τερπνόω</span>/<span class=\"greek\">τερπνέω</span> (não encontrado em outro lugar) deleitar-se, estar feliz AcPl Ha 7, 12. V. <span class=\"greek\">τερπνός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τέρτιος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τέρτιος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (inscr. gr. do I d.C. em GEdmundson, The Church in Rome 1913 p. 22, 1) Tércio, cristão que auxilia Paulo; em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.16.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 16:22</a> ele é <span class=\"greek\">ὁ</span> <span class=\"greek\">γράψας</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">ἐπιστολήν</span>, e envia saudações pessoais à igreja à qual a carta se destina. Cf. Ro subscr.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τέρτουλλος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τέρτουλλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (lit., inscr., moedas) Tértulo. O nome do eparca romano sob o qual Onésimo sofreu o martírio é grafado deste modo em Phlm subscr.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Τέρτυλλος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Τέρτυλλος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (CIG 3001; 4337; IG VII, 4173; XIV, 826, 44; CIL III, 14, 428; 14, 447. Sobre a grafia v. WDittenberger, Her 6, 1872, 293f; B-D-F §41, 1) Tértulo, advogado daqueles que acusaram Paulo perante o procurador Félix <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.24.1\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 24:1f</a>.—SLösch, D. Dankesrede des T.: TQ 112, ’31, 295–319.—Kl. Pauly V 615; BHHW III 1953. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεσσαράκοντα, τεσσαρακονταετής</h1><div class=\"entry-meta\"><span>remissão</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεσσαράκοντα</span>, <span class=\"greek\">τεσσαρακονταετής</span> v. <span class=\"greek\">τεσσερ</span>-.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τέσσαρες</h1><div class=\"entry-meta\"><span>numeral cardinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τέσσαρες</span> (Hom. et al., pseudepígr., apolog.) neut. <span class=\"greek\">τέσσαρα</span> ou <span class=\"greek\">τέσσερα</span> (esta última forma praticamente nunca se encontra em inscr. e pap. [Mayser p. 57 com lit.; Rdm.2 p. 43], mas predomina nos mss. da LXX). Gen. <span class=\"greek\">τεσσάρων</span> (ApcEsdr 3:6 p. 27, 12 Tdf.; ApcMos 33; EpArist; Jos., Vi. 75.—<span class=\"greek\">τὸ</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">τεσσάρων</span> como expr. musical: Dionys. Hal., Comp. Verb. 11). Dat. <span class=\"greek\">τέσσαρσιν</span> (JosAs 24:15; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.11.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 11:5</a> D <span class=\"greek\">τέτρασιν</span>; B-D-F §63, 1). Acus. masc. <span class=\"greek\">τέσσαρας</span> (<span class=\"greek\">τέσσαρες</span> como acus. [pap., LXX; para ambas as formas v. Thackeray 148f] é escassamente atestado para o NT [B-D-F §46, 2; Mlt-H. 130; 170]) quatro <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.24.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 24:31</a> (<span class=\"greek\">ἄνεμος</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 2:3</a> pessoas; 13:27 (<span class=\"greek\">ἄνεμος</span> 2); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.2.37\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 2:37</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.11.17\" target=\"_blank\" rel=\"noopener noreferrer\">J 11:17</a>; 19:23; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.10.11\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 10:11</a> al. (seis vezes ao todo); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:4ab</a> al. (29 vezes); Hv 1, 4, 1 al. (11 vezes). <span class=\"greek\">αἱ</span> <span class=\"greek\">τ</span>. (<span class=\"greek\">παρθένοι</span>) Hs 9, 2, 3; D 10:5 (<span class=\"greek\">ἄνεμος</span> 2). Sobre <span class=\"greek\">τέσσερα</span> <span class=\"greek\">ζῷα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.6\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:6</a> cf. Lohmeyer ad loc.; FDölger, Die Sonne der Gerechtigkeit u. der Schwarze 1918.—DELG. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεσσαρεσκαιδέκατος, η, ον</h1><div class=\"entry-meta\"><span>numeral ordinal</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεσσαρεσκαιδέκατος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> (Hippocr., Epid. 6, 3, 2 L.; SIG 1112, 14; PEleph 1, 1 [311 a.C.]; PYadin 20, 18 al.; POslo 40, 35 [150 d.C.]; LXX [cf. Thackeray 189]; Demetr.: 722 Fgm. 1, 5 Jac.; Jos., Ant. 2, 311 al., C. Ap. 1, 159. A forma jônico-helenística <span class=\"greek\">τεσσερεσκαιδέκατος</span> Hdt. 1, 84; SIG 633, 27 [c. 180 a.C.]; 1017, 10) décimo quarto <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.27.27\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 27:27</a>, 33.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0356-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">τεσσεράκοντα</h1><div class=\"entry-meta\"><span>numeral cardinal indeclinável</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">τεσσεράκοντα</span> (em todo o NT os testemunhos mais antigos apresentam esta forma jônico-helenística; assim também SIG 344, 45 [c. 303 a.C.]; LXX nos unciais [Thackeray 62f; 73]; é duvidoso se o mesmo se pode afirmar dos autógrafos, pois mesmo no I d.C. os pap. quase nunca apresentam <span class=\"greek\">τεσσεράκοντα</span>; para exceções v. BGU 1170, 6 [10 a.C.]; PSI 317, 4 [95 d.C.]. Daí a variação nas edd. críticas, preferindo a maioria delas <span class=\"greek\">τεσσεράκοντα</span>.—B-D-F §29, 1; W-S. §5, 20c; Mlt-H. 66f; Tdf., Proleg. 80; W-H., App. 150.—<span class=\"greek\">τεσσαράκοντα</span> Hom.+; pseudepígr.; Tat. 31, 3) indecl. quarenta, frequentemente de dias (Dicaearchus, Fgm. 35b W. de Pitágoras: <span class=\"greek\">ἀποθανεῖν</span> <span class=\"greek\">τετταράκοντα</span> <span class=\"greek\">ἡμέρας</span> <span class=\"greek\">ἀσιτήσαντα</span>; Diod S 17, 111, 6 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἡμ</span>. <span class=\"greek\">τεττ</span>.; Jos., Ant. 18, 277; Procop., Bell. 6, 15, 7) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 4:2ab</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:13</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.2\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:2</a> (incluindo as noites como Ps.-Callisth. 3, 26, 7 p. 127, 3); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.1.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 1:3</a>. Frequentemente em ref. a Ex 34:28: 1Cl 53:2ab; B 4:7ab; 14:2ab.—Em outros contextos: <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.2.20\" target=\"_blank\" rel=\"noopener noreferrer\">J 2:20</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.22\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:22</a> al. (PMenoud, OCullmann Festschr. ’62, 148–56). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.24\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:24</a> (cf. Jos., Ant. 4, 238; 248); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 3:10</a> (Ps 94:10), 17; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.7.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 7:4</a> al.; Hs 9, 4, 3; 9, 5, 4; 9, 15, 4; 9, 16, 5 (nestas passagens de Hermas ‘quarenta’ aparece como numeral: <span class=\"greek\">μ</span>´).—EKönig, Die Zahl 40 u. Verwandtes: ZDMG 61, 1907, 913–17; WRoscher, Die Zahl 40 im Glauben, Brauch u. Schrifttum der Semiten: ASGLeipz 27, n.º IV 1908, Die Tessarakontaden: BSGLeipz 61, 1909, 21–206; KSchubert, The Dead Sea Community, trad. Doberstein ’59 (simbolismo de ‘40’ em Qumran).—BHHW III 2109.—DELG s.v. <span class=\"greek\">τέσσαρε</span>. M-M. TW.</p></section></article>"};
